+internal sealed class FourLevelU1SymmetricInjectiveMPSDocument : IScribeDocumentDefinition
+{
+    private const string Prefix = "D5/S3/Quantum/SpinChains/FourLevelU1SymmetricInjectiveMPS.";
+    private static readonly LibraryNoteRef Source =
+        LibraryNoteRef.Create("D5/L/StatisticalMechanics/sanzwolfperezgarciacirac2009mps");
+
+    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
+        "Four physical levels with nonzero charge values admit a normalized, symmetric matrix-product family of bond dimension three that is injective at block length two.",
+        H("A symmetric injective matrix-product family with four physical levels"),
+        Blocks(
+            Node("amplitude", "Periodic matrix-product amplitudes", AmplitudeFormula(),
+                "In Symmetries191208.tex, lines 222–237, the amplitude of a periodic, translationally invariant matrix-product state is the trace of the ordered product of its local matrices. "
+                    + "Here a assigns a complex d by d matrix to each of the four physical labels, and w lists the labels along a chain of length n. "
+                    + "The identity ordering retains the order of the sites; at n = 0 the empty product is the identity matrix.",
+                AssessedProvenance.FromLiterature(Source)),
+            Node("u1Rep", "The spectral one-site action", RepresentationFormula(),
+                "Symmetries191208.tex, lines 727–738, considers a local action generated by a Hermitian matrix. "
+                    + "In spectral coordinates, ch gives its four real eigenvalues and w is a unitary change of basis. "
+                    + "The diagonal entries are exp(i φ ch(k)), and conjugation by w expresses the action in the original basis. "
+                    + "The definition accepts arbitrary real eigenvalues and a real parameter φ; it does not impose an integrality or periodicity condition. "
+                    + "The real factors in the exponential are explicitly included in the complex numbers.",
+                AssessedProvenance.FromLiterature(Source)),
+            Node("IsSymmetric", "Symmetry up to a phase", SymmetryFormula(),
+                "Equation (1) of Symmetries191208.tex, lines 134–140, expresses invariance under the tensor power of a one-site action up to a scalar phase. "
+                    + "For every real φ and every positive chain length n, the same one-site matrix acts at every site. "
+                    + "There must be a real θ for which the resulting amplitude function is multiplied by exp(i θ). "
+                    + "The phase may depend on both φ and n. Function.const expresses the constant family of physical label types and the constant family of one-site matrices.",
+                AssessedProvenance.FromLiterature(Source)),
+            Node("IsInjective", "Injectivity of a boundary-to-state map", InjectivityFormula(),
+                "Symmetries191208.tex, lines 267–276, defines injectivity by the existence of a block length for which the map from a boundary matrix x to the amplitudes tr(x a(w(0)) ⋯ a(w(n−1))) is injective. "
+                    + "Thus equality of these amplitudes for every word determines the boundary matrix. "
+                    + "List.ofFn lists the site matrices in order and List.prod multiplies that list. The quantified block length is an arbitrary natural number.",
+                AssessedProvenance.FromLiterature(Source)),
+            Node("claim", "The proposed four-level obstruction", ClaimFormula(),
+                "Symmetries191208.tex, lines 748–751, asks about spin three halves after exhibiting a U(1)-symmetric injective family with only nonzero generator eigenvalues at larger physical dimension, lines 726–746. "
+                    + "The proposition here asks whether every four-level family is noninjective when all four local matrices are nonzero, their products with their conjugate transposes sum to the identity, all four real eigenvalues are nonzero, at least two eigenvalues differ, and the family is symmetric at every positive chain length. "
+                    + "The unitary change of basis and the bond dimension are arbitrary. This is the reading with general generator eigenvalues; lines 719–721 separately give an obstruction for the usual spin generator with equally spaced half-integer eigenvalues.",
+                AssessedProvenance.FromRepo(Source)),
+            Describe.Lean(
+                DescribeId.Create("four-level-u1-result"),
+                DeclarationHandle.Create(Prefix + "result"),
+                H("A normalized injective family of bond dimension three"),
+                StatementSource.FromAuthor(Disp(new Formula.Not(Parenthesized(Local("claim"))))),
+                AssessedProvenance.FromRepo(Source),
+                Blocks(
+                    Paragraph(Text(
+                        "Use bond dimension 3 and the identity change of physical basis. With matrix units Eᵢⱼ indexed by 0, 1, 2, set "
+                            + "A₀ = (3/5)(E₀₁ + E₁₂), A₁ = (4/5)(E₁₀ + E₂₁), A₂ = (4/5)E₀₂ and A₃ = (3/5)E₂₀. "
+                            + "Take the four generator eigenvalues to be (−1, 1, −2, 2). "
+                            + "Each local matrix has a nonzero entry. Direct multiplication gives Σₖ AₖAₖ† = I: "
+                            + "each diagonal entry is 9/25 + 16/25 = 1 and every off-diagonal entry vanishes. "
+                            + "Each eigenvalue is nonzero, and the first two differ.")),
+                    Paragraph(Text(
+                        "For real φ let V(φ) = diag(1, exp(iφ), exp(2iφ)) and V(φ)⁻¹ = diag(1, exp(−iφ), exp(−2iφ)). "
+                            + "Their product is the identity because the exponents cancel in each diagonal entry. "
+                            + "Entrywise multiplication gives V(φ)AₖV(φ)⁻¹ = exp(iφλₖ)Aₖ for each k. "
+                            + "Induction on a list of physical labels extends this identity to its ordered matrix product: "
+                            + "the empty product uses V(φ)V(φ)⁻¹ = I, and the induction step inserts V(φ)⁻¹V(φ) = I between two factors. "
+                            + "Taking traces and using invariance under conjugation shows that the product of the scalar phases times the trace of the word equals the original trace.")),
+                    Paragraph(Text(
+                        "At the identity change of basis the one-site action is diagonal. Its tensor power is diagonal as well, "
+                            + "so its action on a word amplitude is multiplication by the product of exp(iφλₖ) over that word. "
+                            + "The trace identity therefore fixes every periodic amplitude. Choosing θ = 0 establishes symmetry at every positive chain length.")),
+                    Paragraph(Text(
+                        "For injectivity, the length-two products satisfy "
+                            + "A₀A₀ = (9/25)E₀₂, A₁A₁ = (16/25)E₂₀, A₀A₃ = (9/25)E₁₀, A₃A₀ = (9/25)E₂₁, "
